/*
 * CAUSA runtime library (compiler-architecture §6.5).
 *
 * Implements the functions declared in causa_runtime.h: value formatting
 * (language-specification §8.2), show, explain, impact, whatif and assert.
 * Link it with the C generated by `causa emit-c`:
 *
 *     cc -std=c99 -I causa/runtime program.c causa/runtime/causa_runtime.c -lm
 *
 * Everything works from the metadata tables in CAUSA_PROGRAM and the base
 * value environment, which is only ever read here. Output goes to stdout;
 * assertion failures and internal errors go to stderr.
 */
#include "causa_runtime.h"

#include <inttypes.h>
#include <string.h>

#define P CAUSA_PROGRAM

/* ---- internal errors -------------------------------------------------- */

static void causa_internal(const char *what)
{
    fflush(stdout);
    fprintf(stderr, "%s: internal error: %s\n", P.source_file, what);
    exit(2);
}

static void *causa_alloc(size_t count, size_t size)
{
    void *p = calloc(count ? count : 1, size);
    if (!p) causa_internal("out of memory");
    return p;
}

/* Validate the metadata once, so a corrupted table can never cause an
   out-of-range read or unbounded recursion. Dependencies must point to
   earlier bindings, which also makes the graph acyclic. */
static void causa_check_program(void)
{
    static int checked = 0;
    int i, j;
    if (checked) return;
    if (P.node_slots <= 0 || P.node_count < 0 || P.binding_count < 0 || P.assert_count < 0 ||
        (P.node_count > 0 && !P.nodes) || (P.binding_count > 0 && !P.bindings) ||
        (P.assert_count > 0 && !P.asserts))
        causa_internal("malformed program metadata");
    for (i = 0; i < P.node_count; i++) {
        const causa_node_info *n = &P.nodes[i];
        int assert_owner = -1 - n->owner; /* the k of CAUSA_ASSERT_OWNER(k) when owner < 0 */
        if (n->id < 0 || n->id >= P.node_slots || (i > 0 && n->id <= P.nodes[i - 1].id) ||
            n->owner >= P.binding_count || (n->owner < 0 && assert_owner >= P.assert_count))
            causa_internal("malformed node metadata");
    }
    for (i = 0; i < P.binding_count; i++) {
        const causa_binding_info *b = &P.bindings[i];
        if (!b->name || b->anchor < 0 || b->anchor >= P.node_slots || b->type < CAUSA_TYPE_INT ||
            b->type > CAUSA_TYPE_BOOL || b->dep_count < 0 || b->ref_count != b->dep_count ||
            b->dependent_count < 0 || (b->kind == CAUSA_KIND_LET && !b->source_text) ||
            (b->kind == CAUSA_KIND_INPUT && b->dep_count != 0) ||
            (b->dep_count && (!b->deps || !b->refs)) || (b->dependent_count && !b->dependents))
            causa_internal("malformed binding metadata");
        for (j = 0; j < b->dep_count; j++)
            if (b->deps[j] < 0 || b->deps[j] >= i || b->refs[j] < 0 || b->refs[j] >= i)
                causa_internal("malformed dependency metadata");
        for (j = 0; j < b->dependent_count; j++)
            if (b->dependents[j] <= i || b->dependents[j] >= P.binding_count)
                causa_internal("malformed dependency metadata");
    }
    for (i = 0; i < P.assert_count; i++) {
        const causa_assert_info *a = &P.asserts[i];
        if (!a->source_text || a->root < 0 || a->root >= P.node_slots || a->ref_count < 0 ||
            (a->ref_count && !a->refs))
            causa_internal("malformed assert metadata");
        for (j = 0; j < a->ref_count; j++)
            if (a->refs[j] < 0 || a->refs[j] >= P.binding_count) causa_internal("malformed assert metadata");
    }
    checked = 1;
}

/* ---- value formatting (language-specification §8.2) -------------------- */

/* Does mantissa * 10^exponent convert back to exactly v? The string has no
   decimal point, so the result does not depend on the locale's radix. */
static int causa_round_trips(uint64_t mantissa, int exponent, double v)
{
    char buf[48];
    snprintf(buf, sizeof buf, "%" PRIu64 "e%d", mantissa, exponent);
    return strtod(buf, NULL) == v;
}

/* Shortest decimal digits that round-trip to v (v > 0, finite): v is
   mantissa * 10^exponent. For each precision p = 1..17, the correctly rounded
   p-digit value from printf is the nearest p-digit decimal; if it does not
   round-trip, its two neighbours are tried, because the rounding interval of
   a power of two is asymmetric. This reproduces Python's repr digits; it
   relies on the C library's correctly rounded printf("%e") and strtod, which
   tests/test_runtime.py checks against Python on thousands of values. */
static void causa_shortest(double v, uint64_t *mantissa, int *exponent)
{
    int p;
    for (p = 1; p <= 17; p++) {
        char buf[48];
        const char *s;
        uint64_t m = 0;
        int e;
        snprintf(buf, sizeof buf, "%.*e", p - 1, v);
        for (s = buf; *s && *s != 'e' && *s != 'E'; s++)
            if (*s >= '0' && *s <= '9') m = m * 10 + (uint64_t)(*s - '0'); /* skips the radix */
        e = atoi(s + 1) - (p - 1);
        if (causa_round_trips(m, e, v)) { *mantissa = m; *exponent = e; return; }
        if (causa_round_trips(m + 1, e, v)) { *mantissa = m + 1; *exponent = e; return; }
        if (m > 1 && causa_round_trips(m - 1, e, v)) { *mantissa = m - 1; *exponent = e; return; }
    }
    causa_internal("float formatting failed"); /* unreachable: 17 digits always round-trip */
}

static void causa_format_double(double x, char *out, size_t size)
{
    char digits[24], body[48], *p = body;
    uint64_t m;
    int e, n, point, i;
    if (!isfinite(x)) causa_internal("non-finite float value"); /* never a CAUSA value */
    if (x == 0.0) {
        snprintf(out, size, "%s", signbit(x) ? "-0.0" : "0.0");
        return;
    }
    causa_shortest(fabs(x), &m, &e);
    while (m % 10 == 0) { m /= 10; e++; } /* strip trailing zeros */
    n = snprintf(digits, sizeof digits, "%" PRIu64, m);
    point = e + n - 1; /* decimal exponent of the first digit */
    if (point >= -4 && point < 16) { /* positional, at least one digit after the point */
        if (point < 0) {
            *p++ = '0';
            *p++ = '.';
            for (i = 0; i < -point - 1; i++) *p++ = '0';
            strcpy(p, digits);
        } else {
            for (i = 0; i <= point; i++) *p++ = i < n ? digits[i] : '0';
            *p++ = '.';
            strcpy(p, point + 1 < n ? digits + point + 1 : "0");
        }
    } else { /* d[.ddd]e±XX */
        *p++ = digits[0];
        if (n > 1) {
            *p++ = '.';
            strcpy(p, digits + 1);
            p += n - 1;
        }
        snprintf(p, sizeof body - (size_t)(p - body), "e%c%02d", point < 0 ? '-' : '+', point < 0 ? -point : point);
    }
    snprintf(out, size, "%s%s", signbit(x) ? "-" : "", body);
}

void causa_format_value(int type, causa_value value, char *out, size_t size)
{
    if (type == CAUSA_TYPE_INT) snprintf(out, size, "%" PRId64, value.i);
    else if (type == CAUSA_TYPE_FLOAT) causa_format_double(value.f, out, size);
    else snprintf(out, size, "%s", value.b ? "true" : "false");
}

/* ---- helpers ---------------------------------------------------------- */

static const char *causa_value_text(int binding, const causa_value *env, char *buf)
{
    const causa_binding_info *b = &P.bindings[binding];
    causa_format_value(b->type, env[b->anchor], buf, CAUSA_VALUE_BUFSIZE);
    return buf;
}

static void causa_check_binding(int binding)
{
    causa_check_program();
    if (binding < 0 || binding >= P.binding_count) causa_internal("binding index out of range");
}

/* Print "label: a, b, c" for the bindings flagged in `set`, in declaration order. */
static void causa_print_list(const char *label, const unsigned char *set)
{
    int i, any = 0;
    printf("  %s: ", label);
    for (i = 0; i < P.binding_count; i++) {
        if (!set[i]) continue;
        printf("%s%s", any ? ", " : "", P.bindings[i].name);
        any = 1;
    }
    printf("%s\n", any ? "" : "(none)");
}

/* ---- show (§8.3) -------------------------------------------------------- */

void causa_show(const causa_value *env, int binding)
{
    char v[CAUSA_VALUE_BUFSIZE];
    causa_check_binding(binding);
    printf("%s = %s\n", P.bindings[binding].name, causa_value_text(binding, env, v));
}

/* ---- explain (§8.4) ----------------------------------------------------- */

static void causa_explain_node(const causa_value *env, int binding, int depth, unsigned char *printed)
{
    const causa_binding_info *b = &P.bindings[binding];
    char v[CAUSA_VALUE_BUFSIZE];
    int j;
    const char *kind = b->kind == CAUSA_KIND_INPUT ? "input" : "let";
    printf("%*s%s = %s  ", 2 * (depth + 1), "", b->name, causa_value_text(binding, env, v));
    if (printed[binding]) {
        printf("[%s, see above]\n", kind);
        return;
    }
    printed[binding] = 1;
    if (b->kind == CAUSA_KIND_INPUT) {
        printf("[input]\n");
        return;
    }
    printf("[let: %s]\n", b->source_text);
    /* refs are strictly earlier bindings (checked), so recursion depth is bounded */
    for (j = 0; j < b->ref_count; j++) causa_explain_node(env, b->refs[j], depth + 1, printed);
}

void causa_explain(const causa_value *env, int binding)
{
    const causa_binding_info *b;
    unsigned char *printed, *direct, *reach, *inputs, *lets;
    int i, j;
    causa_check_binding(binding);
    b = &P.bindings[binding];
    printed = causa_alloc((size_t)P.binding_count, 1);
    direct = causa_alloc((size_t)P.binding_count, 1);
    reach = causa_alloc((size_t)P.binding_count, 1);
    inputs = causa_alloc((size_t)P.binding_count, 1);
    lets = causa_alloc((size_t)P.binding_count, 1);

    printf("explain %s\n", b->name);
    causa_explain_node(env, binding, 0, printed);

    for (j = 0; j < b->dep_count; j++) direct[b->deps[j]] = reach[b->deps[j]] = 1;
    for (i = binding - 1; i >= 0; i--) /* deps point backwards: one reverse sweep closes the set */
        if (reach[i])
            for (j = 0; j < P.bindings[i].dep_count; j++) reach[P.bindings[i].deps[j]] = 1;
    for (i = 0; i < P.binding_count; i++) {
        inputs[i] = reach[i] && P.bindings[i].kind == CAUSA_KIND_INPUT;
        lets[i] = reach[i] && P.bindings[i].kind == CAUSA_KIND_LET;
    }
    causa_print_list("direct dependencies", direct);
    causa_print_list("transitive dependencies", reach);
    causa_print_list("inputs", inputs);
    causa_print_list("intermediates", lets);
    free(printed); free(direct); free(reach); free(inputs); free(lets);
}

/* ---- impact (§8.6) ------------------------------------------------------ */

/* Visible lets depending on `binding`: dependents always follow it in
   declaration order, so one forward sweep finds the transitive set. */
static void causa_cone(int binding, int visible, unsigned char *cone)
{
    int i, j;
    for (i = binding + 1; i < visible && i < P.binding_count; i++)
        for (j = 0; j < P.bindings[i].dep_count; j++) {
            int d = P.bindings[i].deps[j];
            if (d == binding || cone[d]) { cone[i] = 1; break; }
        }
}

void causa_impact(const causa_value *env, int binding, int visible)
{
    const causa_binding_info *b;
    unsigned char *direct, *all;
    int j;
    (void)env; /* impact is purely structural: no values are read */
    causa_check_binding(binding);
    b = &P.bindings[binding];
    direct = causa_alloc((size_t)P.binding_count, 1);
    all = causa_alloc((size_t)P.binding_count, 1);
    for (j = 0; j < b->dependent_count; j++)
        if (b->dependents[j] < visible) direct[b->dependents[j]] = 1;
    causa_cone(binding, visible, all);
    printf("impact %s\n", b->name);
    causa_print_list("direct dependents", direct);
    causa_print_list("all dependents", all);
    free(direct); free(all);
}

/* ---- whatif (§8.5) ------------------------------------------------------ */

enum { CAUSA_OUTCOME_BASE = 0, CAUSA_OUTCOME_VALUE, CAUSA_OUTCOME_FAILED, CAUSA_OUTCOME_UNAVAILABLE };

static int causa_same_value(int type, causa_value a, causa_value b)
{
    if (type == CAUSA_TYPE_INT) return a.i == b.i;
    if (type == CAUSA_TYPE_BOOL) return a.b == b.b;
    return memcmp(&a.f, &b.f, sizeof a.f) == 0; /* same bits: 0.0 and -0.0 differ */
}

static void causa_outcome_line(int i, const causa_value *env, const causa_value *cf, const int *state,
                               const causa_error *errors, const int *cause)
{
    const causa_binding_info *b = &P.bindings[i];
    char base[CAUSA_VALUE_BUFSIZE], now[CAUSA_VALUE_BUFSIZE];
    printf("  %s: %s -> ", b->name, causa_value_text(i, env, base));
    if (state[i] == CAUSA_OUTCOME_FAILED)
        printf("error[R%d] at %d:%d (%s)\n", errors[i].code, errors[i].line, errors[i].column,
               causa_error_description(errors[i].code));
    else if (state[i] == CAUSA_OUTCOME_UNAVAILABLE)
        printf("unavailable (depends on %s)\n", P.bindings[cause[i]].name);
    else
        printf("%s%s\n", causa_value_text(i, cf, now),
               causa_same_value(b->type, env[b->anchor], cf[b->anchor]) ? "  (unchanged)" : "");
}

void causa_whatif(const causa_value *env, int input_binding, causa_value value, int target_binding,
                  int visible)
{
    const causa_binding_info *in;
    causa_value *cf;
    unsigned char *cone;
    int *state, *cause, i, j, k, any = 0;
    causa_error *errors;
    char v[CAUSA_VALUE_BUFSIZE], base[CAUSA_VALUE_BUFSIZE];

    causa_check_binding(input_binding);
    in = &P.bindings[input_binding];
    if (in->kind != CAUSA_KIND_INPUT || visible > P.binding_count || target_binding >= visible)
        causa_internal("invalid whatif request");

    /* A fresh counterfactual environment: the base environment is never written. */
    cf = causa_alloc((size_t)P.node_slots, sizeof *cf);
    memcpy(cf, env, (size_t)P.node_slots * sizeof *cf);
    cf[in->anchor] = value;
    cone = causa_alloc((size_t)P.binding_count, 1);
    state = causa_alloc((size_t)P.binding_count, sizeof *state);
    cause = causa_alloc((size_t)P.binding_count, sizeof *cause);
    errors = causa_alloc((size_t)P.binding_count, sizeof *errors);
    causa_cone(input_binding, visible, cone);

    for (i = 0; i < P.binding_count; i++) {
        const causa_binding_info *b = &P.bindings[i];
        int earliest = -1;
        if (!cone[i]) continue;
        for (j = 0; j < b->dep_count; j++) { /* unavailable if a dependency failed */
            int d = b->deps[j], c = -1;
            if (state[d] == CAUSA_OUTCOME_FAILED) c = d;
            else if (state[d] == CAUSA_OUTCOME_UNAVAILABLE) c = cause[d];
            if (c >= 0 && (earliest < 0 || c < earliest)) earliest = c;
        }
        if (earliest >= 0) {
            state[i] = CAUSA_OUTCOME_UNAVAILABLE;
            cause[i] = earliest;
            continue;
        }
        state[i] = CAUSA_OUTCOME_VALUE;
        /* ponytail: scans every node per binding (O(bindings * nodes)); index by owner if programs grow large */
        for (k = 0; k < P.node_count; k++) {
            if (P.nodes[k].owner != i) continue;
            if (causa_eval_node(P.nodes[k].id, cf, &errors[i])) {
                state[i] = CAUSA_OUTCOME_FAILED;
                break;
            }
        }
    }

    causa_format_value(in->type, value, v, sizeof v);
    printf("whatif %s = %s", in->name, v);
    if (target_binding >= 0) {
        printf(" show %s\n", P.bindings[target_binding].name);
        if (!cone[target_binding]) causa_internal("whatif target does not depend on the input");
        causa_outcome_line(target_binding, env, cf, state, errors, cause);
    } else {
        printf("\n  %s: %s -> %s  (override)\n", in->name, causa_value_text(input_binding, env, base), v);
        for (i = 0; i < P.binding_count; i++)
            if (cone[i]) {
                causa_outcome_line(i, env, cf, state, errors, cause);
                any = 1;
            }
        if (!any) printf("  (no dependent bindings)\n");
    }
    free(cf); free(cone); free(state); free(cause); free(errors);
}

/* ---- assert (§8.7, §9.3) ------------------------------------------------ */

void causa_assert(const causa_value *env, int assert_index, bool ok)
{
    const causa_assert_info *a;
    char v[CAUSA_VALUE_BUFSIZE];
    int j;
    if (ok) return;
    causa_check_program();
    if (assert_index < 0 || assert_index >= P.assert_count) causa_internal("assert index out of range");
    a = &P.asserts[assert_index];
    fflush(stdout);
    fprintf(stderr, "%s:%d:%d: assertion failed: %s\n", P.source_file, a->line, a->column, a->source_text);
    for (j = 0; j < a->ref_count; j++)
        fprintf(stderr, "  %s = %s\n", P.bindings[a->refs[j]].name, causa_value_text(a->refs[j], env, v));
    exit(1);
}
